  const brand=$('sellerBrand'),summary=$('sellerSummary');seller.replaceChildren();
  seller.innerHTML=`<div class="vendor-portal"><header class="vendor-portal-bar"><button type="button" class="vendor-menu-toggle" aria-label="Toggle seller menu" aria-expanded="false">☰</button><div><small>SELLER PORTAL</small><h1 id="vendorStoreName">Your store</h1></div><span id="vendorStoreState" class="vendor-state"></span></header><div class="vendor-portal-layout"><nav class="vendor-portal-nav" aria-label="Seller navigation">${[['overview','Overview'],['products','Products'],['orders','Orders'],['inventory','Inventory'],['settlements','Sales & settlements'],['store','Store details']].map(([key,title])=>`<button type="button" data-vendor-tab="${key}">${title}</button>`).join('')}<button type="button" data-page="support">Support</button><button type="button" data-account-signout>Sign out</button></nav><div class="vendor-portal-main"><div class="vendor-store-selector"><label for="sellerBrand">Store</label></div><div id="vendorPending" hidden></div><div id="vendorOverview" class="vendor-panel"></div><div id="vendorProductsPanel" class="vendor-panel"></div><div id="vendorOrdersPanel" class="vendor-panel"></div><div id="vendorStorePanel" class="vendor-panel"></div></div></div></div>`;
  seller.querySelector('.vendor-store-selector').append(brand);$('vendorProductsPanel').append($('sellerProducts')||api.productSection);seller.querySelector('.vendor-portal-main').append(settlement);summary.hidden=true;settlement.prepend(summary);
  seller.addEventListener('click',e=>{const button=e.target.closest('[data-vendor-tab]');if(button){show(button.dataset.vendorTab);if(button.dataset.newProduct)api.newProduct();return}if(e.target.closest('.vendor-menu-toggle')){const open=seller.classList.toggle('vendor-menu-open');e.target.closest('button').setAttribute('aria-expanded',String(open))}const pager=e.target.closest('[data-vendor-page]');if(pager){page+=Number(pager.dataset.vendorPage);refresh().catch(api.error)}const detail=e.target.closest('[data-vendor-order]');if(detail){const panel=$(detail.dataset.vendorOrder);panel.hidden=!panel.hidden;detail.setAttribute('aria-expanded',String(!panel.hidden))}});
  $('vendorSignupForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]'),status=f.querySelector('[role=status]');if(b.disabled)return;b.disabled=true;status.textContent='Creating your seller account…';try{const r=await api.db.auth.signUp({email:f.elements.email.value.trim(),password:f.elements.password.value,options:{emailRedirectTo:location.origin+location.pathname+'#vendor-register',data:{registration_type:'vendor',vendor_invitation:f.elements.invitation.value.trim().toUpperCase(),full_name:f.elements.fullName.value.trim(),phone:f.elements.phone.value.trim(),country_code:f.elements.country.value,gender:f.elements.gender.value,terms_accepted:f.elements.consent.checked?'true':'false'}}});if(r.error)throw r.error;f.elements.password.value='';status.textContent='Check your email to verify your seller account, then sign in to complete the application.';if(r.data?.session)await api.signedUp(r.data.session)}catch(error){status.textContent=error.message}finally{b.disabled=false}};
